+package compiler.valhalla.valuetypes;
+
+/*
+ * @test
+ * @bug 8393467
+ * @summary Test that temporary GraphKit map is killed after flat access expansion
+ * @enablePreview
+ * @run main/othervm -Xbatch ${test.main.class}
+ */
+public class TestReducePhiWithFlatAccess {
+    static class Test {
+        Integer i;
+    }
+
+    static void sink(Object a, Object b) { }
+
+    static void testLoad(boolean b) {
+        sink(b ? new Test() : null, new Test().i);
+    }
+
+    static void testStore(boolean b) {
+        sink(b ? new Test() : null, new Test().i = 42);
+    }
+
+    public static void main(String[] args) {
+        for (int i = 0; i < 10_000; i++) {
+            boolean b = (i & 1) == 0;
+            testLoad(b);
+            testStore(b);
+        }
+    }
+}
